def _embedded_list():
    return list(_EMBEDDED_MODELS_B64.keys())

def _embedded_load(name):
    import base64 as _b64
    import gzip as _gz
    import io as _io
    import joblib as _jl
    raw = _gz.decompress(_b64.b64decode(_EMBEDDED_MODELS_B64[name]))
    return _jl.load(_io.BytesIO(raw))

