# Models-registered banner
# =========================================================
if EMBEDDED_AVAILABLE:
    chips = "".join(
        f"<span>{n}</span>" for n in _EMBEDDED_NAMES
    )
    st.markdown(
        f"""
        <div class="models-banner">
            <div class="title">✓ {len(_EMBEDDED_NAMES)} model(s) registered</div>
            <div class="chips">{chips}</div>
        </div>
        """,
        unsafe_allow_html=True,
    )
else:
    st.error(
        "⚠️ No embedded models detected. Please paste the embedded models "
        "module (with `_embedded_list()` and `_embedded_load(name)`) at the "
        "top of this file."
    )

# =========================================================
# BIG BOLD TABS — top-level navigation
# =========================================================
tab_data, tab_manual, tab_log = st.tabs(
    ["📊  Dataset Prediction", "🧪  Manual Test", "📜  Log"]
)

# =========================================================
# Tab 1 — Dataset prediction
# =========================================================
with tab_data:
    # ---------------- Step 1 : dataset upload ----------------
    st.markdown(
        """
        <div class="step-title">
            <div class="step-num">1</div>
            <div class="step-text">
                <h2>Upload Dataset</h2>
                <p>Excel or CSV file containing the input features.</p>
            </div>
        </div>
        """,
        unsafe_allow_html=True,
    )

    up_ds = st.file_uploader(
        "Upload Excel / CSV",
        type=["xlsx", "xls", "csv"],
        key="dataset_uploader",
    )

    if up_ds is not None:
        try:
            if up_ds.name.lower().endswith((".xlsx", ".xls")):
                df = pd.read_excel(up_ds, sheet_name=0)
            else:
                try:
                    df = pd.read_csv(up_ds, encoding="utf-8-sig")
                except UnicodeDecodeError:
                    up_ds.seek(0)
                    df = pd.read_csv(up_ds, encoding="latin-1")

            df.columns = [str(c).strip() for c in df.columns]

            before = list(df.columns)
            df = _auto_generate_steel_onehot(df)
            after = list(df.columns)
            added_skin = [c for c in after if c not in before]

            before2 = list(df.columns)
            df = _add_derived_features(df)
            after2 = list(df.columns)
            added_derived = [c for c in after2 if c not in before2]

            st.session_state.df_new = df
            if TARGET_COL in df.columns:
                st.session_state.y_measured = pd.to_numeric(
                    df[TARGET_COL], errors="coerce"
                ).reset_index(drop=True)
            else:
                st.session_state.y_measured = None

            st.success(f"Loaded: **{up_ds.name}** — {df.shape[0]} rows × {df.shape[1]} cols")
            if added_skin:
                st.info(f"[AUTO] Generated columns: `{added_skin}`")
            if added_derived:
                st.info(f"[AUTO] Computed derived features: `{added_derived}`")

            with st.expander("Preview dataset (first 10 rows)", expanded=False):
                st.dataframe(_rename_with_units(df.head(10)),
                             use_container_width=True)

            problems = _find_dataset_range_problems(df)
            if problems:
                n_rows = len(set(p[0] for p in problems))
                st.warning(
                    f"⚠️ {len(problems)} out-of-range value(s) in {n_rows} row(s).\n\n"
                    f"{_format_dataset_problems(problems)}\n\n"
                    f"(Excel row numbers: header is row 1, first sample is row 2.)"
                )
        except Exception as e:
            st.error(f"Read error: {type(e).__name__}: {e}")
            st.code(traceback.format_exc())

    # ---------------- Step 2 : select models ----------------
    st.markdown(
        """
        <div class="step-title">
            <div class="step-num">2</div>
            <div class="step-text">
                <h2>Select Models</h2>
                <p>Tick the models you want to run on this dataset.</p>
            </div>
        </div>
        """,
        unsafe_allow_html=True,
    )

    all_model_names = list(st.session_state.model_registry.keys())
    if not all_model_names:
        st.info("No models registered. Please ensure the embedded models are present.")
        selected_models = []
    else:
        # --- Initialize checkbox states once ---
        for name in all_model_names:
            skey = f"ds_model_sel__{name}"
            if skey not in st.session_state:
                st.session_state[skey] = True

        # --- Bulk action buttons ---
        bc1, bc2, _spacer = st.columns([1, 1, 5])
        with bc1:
            if st.button("✓  Select All", key="ds_btn_select_all",
                         use_container_width=True):
                for name in all_model_names:
                    st.session_state[f"ds_model_sel__{name}"] = True
                st.rerun()
        with bc2:
            if st.button("✗  Delete All", key="ds_btn_delete_all",
                         use_container_width=True):
                for name in all_model_names:
                    st.session_state[f"ds_model_sel__{name}"] = False
                st.rerun()

        # --- Checkbox grid ---
        ncol = 3
        grid_cols = st.columns(ncol)
        selected_models = []
        for i, name in enumerate(all_model_names):
            with grid_cols[i % ncol]:
                if st.checkbox(name, key=f"ds_model_sel__{name}"):
                    selected_models.append(name)

    # ---------------- Step 3 : run ----------------
    st.markdown(
        """
        <div class="step-title">
            <div class="step-num">3</div>
            <div class="step-text">
                <h2>Run Prediction</h2>
                <p>Execute all selected models and view results.</p>
            </div>
        </div>
        """,
        unsafe_allow_html=True,
    )

    run_clicked = st.button(
        "▶ Run Prediction",
        type="primary",
        disabled=(not selected_models or st.session_state.df_new is None),
    )

    if run_clicked:
        df_new = st.session_state.df_new
        per_model, succeeded, failed = {}, [], []
        progress = st.progress(0.0, text="Starting…")
        n = len(selected_models)

        for i, name in enumerate(selected_models):
            progress.progress(i / n, text=f"Running {name} …")
            try:
                model = _get_model(name)
            except Exception as e:
                failed.append((name, f"load failed: {type(e).__name__}: {e}"))
                continue

            feats = get_model_feature_names(model)
            user_by_canon = {}
            for c in df_new.columns:
                canon = canonical_of(c)
                if canon and canon not in user_by_canon:
                    user_by_canon[canon] = c

            try:
                if feats is None:
                    X_use = df_new.drop(columns=[TARGET_COL], errors="ignore").copy()
                else:
                    out = pd.DataFrame(index=df_new.index)
                    missing = []
                    for feat in feats:
                        if feat in df_new.columns:
                            out[feat] = pd.to_numeric(df_new[feat], errors="coerce").values
                            continue
                        canon = canonical_of(feat)
                        if canon and canon in user_by_canon:
                            src = user_by_canon[canon]
                            out[feat] = pd.to_numeric(df_new[src], errors="coerce").values
                            continue
                        out[feat] = None
                        missing.append(feat)
                    if missing:
                        raise ValueError(f"missing features: {missing}")
                    X_use = out

                y_pred = np.asarray(model.predict(X_use)).ravel()
                per_model[name] = y_pred
                succeeded.append(name)
            except Exception as e:
                failed.append((name, f"{type(e).__name__}: {e}"))

        progress.progress(1.0, text="Done.")

        results = (pd.DataFrame({f"{m}_Pred": per_model[m] for m in succeeded})
                   if succeeded else pd.DataFrame())
        st.session_state.predictions_df = results
        st.session_state.success_models = succeeded
        st.session_state.failed_models = failed

        metrics_rows = []
        y_meas = st.session_state.y_measured
        if y_meas is not None and not results.empty:
            y_true = y_meas.values.astype(float)
            for m in succeeded:
                col = f"{m}_Pred"
                mt = compute_metrics(y_true, results[col].values)
                if mt is not None:
                    metrics_rows.append({
                        "Model": m, "N": mt["N"],
                        "R2": mt["R2"], "RMSE": mt["RMSE"],
                        "MAE": mt["MAE"], "MAPE (%)": mt["MAPE (%)"],
                    })
        metrics_df = pd.DataFrame(metrics_rows) if metrics_rows else None
        if metrics_df is not None and len(metrics_df) > 1:
            metrics_df = rank_models(metrics_df)
        st.session_state.metrics_df = metrics_df

        base = df_new.drop(columns=[TARGET_COL], errors="ignore").reset_index(drop=True)
        st.session_state.output_df = (
            pd.concat([base, results.reset_index(drop=True)], axis=1)
            if not results.empty else base
        )

        log(f"==== Dataset Prediction ====")
        log(f"  succeeded = {succeeded}")
        log(f"  failed    = {failed}")

    # ---------------- Results ----------------
    if (st.session_state.predictions_df is not None
            and not st.session_state.predictions_df.empty):

        st.subheader("📈 Predictions")
        st.dataframe(
            _rename_with_units(st.session_state.predictions_df.head(1000)),
            use_container_width=True,
        )

        if st.session_state.metrics_df is not None:
            st.subheader("🏆 Metrics & Ranking")
            st.dataframe(st.session_state.metrics_df, use_container_width=True)
            best = st.session_state.metrics_df.iloc[0]
            st.success(
                f"★ Best model: **{best['Model']}** "
                f"(R² = {best['R2']:.4f} | MAPE = {best['MAPE (%)']:.2f}%)"
            )

        st.subheader("⬇ Download results")
        stamp = f"{datetime.now():%Y%m%d_%H%M%S}"

        export_df = _prepare_export_df(st.session_state.output_df)

        csv_bytes = export_df.to_csv(
            index=False, encoding="utf-8-sig"
        ).encode("utf-8-sig")
        st.download_button(
            "Download CSV (all predictions)",
            data=csv_bytes,
            file_name=f"predictions_{stamp}.csv",
            mime="text/csv",
        )

        buf = io.BytesIO()
        with pd.ExcelWriter(buf, engine="openpyxl") as writer:
            used = set()
            def _w(df_, base_name):
                name = safe_sheet_name(base_name)
                orig, i = name, 1
                while name in used:
                    sfx = f"_{i}"
                    name = (orig[:31 - len(sfx)]) + sfx
                    i += 1
                used.add(name)
                df_.to_excel(writer, sheet_name=name, index=False)

            _w(_prepare_export_df(
                    st.session_state.predictions_df.reset_index(drop=True)),
               "All_Predictions")

            base_df = st.session_state.df_new.reset_index(drop=True)
            for m in st.session_state.success_models:
                pcol = f"{m}_Pred"
                if pcol not in st.session_state.predictions_df.columns:
                    continue
                sheet_df = base_df.copy()
                sheet_df[pcol] = st.session_state.predictions_df[pcol].values
                _w(_prepare_export_df(sheet_df), m)

        buf.seek(0)
        st.download_button(
            "Download Excel (multi-sheet)",
            data=buf.getvalue(),
            file_name=f"predictions_{stamp}.xlsx",
            mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        )

        if st.session_state.failed_models:
            st.warning(
                "Some models failed:\n\n"
                + "\n".join(f"• {n}: {m}"
                            for n, m in st.session_state.failed_models)
            )

# =========================================================
# Tab 2 — Manual Test
# =========================================================
with tab_manual:
    st.subheader("🧪 Manual Test")
    st.caption(
        "Enter values row-by-row, pick a skin type if the model needs it, "
        "and run predictions using one selected model. "
        "Values outside the acceptable range are shown with a red border in the cell."
    )

    all_model_names = list(st.session_state.model_registry.keys())
    if not all_model_names:
        st.info("No models registered. Please ensure the embedded models are present.")
    else:
        # ---- Prominent model selector (styled via CSS .st-key-mt_model) ----
        mt_model = st.selectbox(
            "🎯  Choose a Model to Run",
            options=all_model_names,
            key="mt_model",
        )
        model = _get_model(mt_model)
        feats = get_model_feature_names(model)

        if feats is None:
            st.error("Selected model has no `feature_names_in_` attribute.")
        else:
            input_feats, derived_feats, skin_feats = [], [], []
            for f in feats:
                c = canonical_of(f)
                if c in DERIVED_FEATURES:
                    derived_feats.append(f)
                elif c in SKIN_TYPE_FEATURES:
                    skin_feats.append(f)
                else:
                    input_feats.append(f)

            if input_feats:
                with st.expander("📏 Acceptable ranges", expanded=False):
                    rows = []
                    for f in input_feats:
                        c = canonical_of(f)
                        if c in FEATURE_RANGES:
                            lo, hi = FEATURE_RANGES[c]
                            rows.append({
                                "Feature": f,
                                "Unit": (unit_of(f) or "").replace("-", ""),
                                "Min": lo,
                                "Max": hi,
                            })
                    if rows:
                        st.dataframe(pd.DataFrame(rows), use_container_width=True)

            n_rows = st.number_input(
                "Number of rows to enter:",
                min_value=1, max_value=200, value=3, step=1,
            )

            init_data = {f: [np.nan] * n_rows for f in input_feats}
            if skin_feats:
                init_data["Skin Type"] = ["Carbon Steel"] * n_rows
            init_df = pd.DataFrame(init_data)

            column_config = {}
            for f in input_feats:
                c = canonical_of(f)
                if c in FEATURE_RANGES:
                    lo, hi = FEATURE_RANGES[c]
                    column_config[f] = st.column_config.NumberColumn(
                        f,
                        min_value=float(lo),
                        max_value=float(hi),
                        format="%g",
                        help=f"Valid range: {lo:g} … {hi:g}",
                    )
                else:
                    column_config[f] = st.column_config.NumberColumn(
                        f, format="%g",
                    )

            if skin_feats:
                column_config["Skin Type"] = st.column_config.SelectboxColumn(
                    "Skin Type",
                    options=SKIN_TYPE_OPTIONS,
                    required=True,
                    default="Carbon Steel",
                )

            edited = st.data_editor(
                init_df,
                num_rows="dynamic",
                use_container_width=True,
                column_config=column_config,
                key="mt_editor",
            )

            # ---- LIVE VALIDATION ----
            live_warnings = []
            for row_idx, r in edited.iterrows():
                for f in input_feats:
                    v = r[f]
                    if pd.isna(v) or str(v).strip() == "":
                        continue
                    c = canonical_of(f)
                    if c is None or c not in FEATURE_RANGES:
                        continue
                    ok, reason = _check_value_or_reason(c, v)
                    if not ok:
                        lo, hi = FEATURE_RANGES[c]
                        live_warnings.append(
                            f"• Row {row_idx + 1} — `{f}` = **{v}**  "
                            f"(valid: {lo:g} … {hi:g} — {reason})"
                        )

            if live_warnings:
                st.warning(
                    "⚠️ **Out-of-range value(s) detected in the table above.** "
                    "The offending cell(s) are highlighted in red. "
                    "Please correct them before running:\n\n"
                    + "\n".join(live_warnings)
                )

            if st.button("▶ Run Manual Prediction", type="primary"):
                rows_data = []
                for _, r in edited.iterrows():
                    vals = {f: r[f] for f in input_feats}
                    if all(pd.isna(v) or str(v).strip() == ""
                           for v in vals.values()):
                        continue
                    skin = (r.get("Skin Type", "Carbon Steel")
                            if skin_feats else "—")

                    out_of_range = []
                    for f in input_feats:
                        v = r[f]
                        if pd.isna(v) or str(v).strip() == "":
                            continue
                        c = canonical_of(f)
                        ok, reason = _check_value_or_reason(c, v)
                        if not ok:
                            out_of_range.append((f, v, reason))

                    rows_data.append({
                        "vals": vals,
                        "skin": skin,
                        "out_of_range": out_of_range,
                    })

                if not rows_data:
                    st.warning("No non-empty rows to predict.")
                else:
                    has_oob = any(rr["out_of_range"] for rr in rows_data)
                    if has_oob:
                        lines = []
                        for i, rr in enumerate(rows_data):
                            for f, v, reason in rr["out_of_range"]:
                                lines.append(f"• Row {i+1}: `{f}` = {v}  ({reason})")
                        st.warning(
                            "⚠️ Out-of-range value(s) detected:\n\n"
                            + "\n".join(lines)
                            + "\n\nValues will still be predicted, but the model "
                              "may produce unreliable results."
                        )

                    X_rows = []
                    for rr in rows_data:
                        canon_base = {}
                        for f in input_feats:
                            c = canonical_of(f)
                            v = rr["vals"][f]
                            if pd.isna(v) or str(v).strip() == "":
                                canon_base[c] = np.nan
                            else:
                                try:
                                    canon_base[c] = float(v)
                                except (ValueError, TypeError):
                                    canon_base[c] = np.nan

                        derived = compute_derived_features(canon_base)
                        rr["derived"] = derived

                        skin_vals = (SKIN_TYPE_MAP.get(rr["skin"], {})
                                     if skin_feats else {})

                        feat_vals = {}
                        for f in feats:
                            c = canonical_of(f)
                            if c in DERIVED_FEATURES:
                                v = derived.get(c, np.nan)
                                if v is None or (isinstance(v, float)
                                                 and np.isnan(v)):
                                    v = 0.0
                                feat_vals[f] = float(v)
                            elif c in SKIN_TYPE_FEATURES:
                                feat_vals[f] = float(skin_vals.get(c, 0))
                            else:
                                v = rr["vals"].get(f, np.nan)
                                try:
                                    feat_vals[f] = (float(v)
                                                    if not pd.isna(v)
                                                    else np.nan)
                                except (ValueError, TypeError):
                                    feat_vals[f] = np.nan
                        X_rows.append(feat_vals)

                    X = pd.DataFrame(X_rows, columns=feats)
                    try:
                        y_pred = np.asarray(model.predict(X)).ravel()
                    except Exception as e:
                        st.error(f"Predict error: {type(e).__name__}: {e}")
                        st.code(traceback.format_exc())
                    else:
                        res_data = {"#": list(range(1, len(rows_data) + 1))}
                        for f in input_feats:
                            res_data[f] = [rr["vals"].get(f, np.nan)
                                           for rr in rows_data]
                        if skin_feats:
                            res_data["Skin Type"] = [rr["skin"]
                                                     for rr in rows_data]
                        for f in derived_feats:
                            c = canonical_of(f)
                            res_data[f] = [rr["derived"].get(c, np.nan)
                                           for rr in rows_data]
                        res_data["Predicted_Nu"] = y_pred

                        res_df = pd.DataFrame(res_data)
                        res_df_display = _rename_with_units(res_df)

                        st.success(f"✓ Predicted {len(rows_data)} row(s)")
                        st.dataframe(res_df_display, use_container_width=True)

                        stamp = f"{datetime.now():%Y%m%d_%H%M%S}"

                        csv_bytes = res_df_display.to_csv(
                            index=False, encoding="utf-8-sig"
                        ).encode("utf-8-sig")
                        st.download_button(
                            "Download results (CSV)",
                            data=csv_bytes,
                            file_name=f"manual_test_{stamp}.csv",
                            mime="text/csv",
                            key="mt_csv_dl",
                        )

                        buf = io.BytesIO()
                        with pd.ExcelWriter(buf, engine="openpyxl") as writer:
                            used = set()
                            def _w(df_, base_name):
                                name = safe_sheet_name(base_name)
                                orig, i = name, 1
                                while name in used:
                                    sfx = f"_{i}"
                                    name = (orig[:31 - len(sfx)]) + sfx
                                    i += 1
                                used.add(name)
                                df_.to_excel(writer, sheet_name=name,
                                             index=False)
                            _w(res_df_display.reset_index(drop=True),
                               "All_Predictions")
                            _w(res_df_display.reset_index(drop=True), mt_model)

                        buf.seek(0)
                        st.download_button(
                            "Download results (Excel multi-sheet)",
                            data=buf.getvalue(),
                            file_name=f"manual_test_{stamp}.xlsx",
                            mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                            key="mt_xlsx_dl",
                        )

# =========================================================
# Tab 3 — Log
# =========================================================
with tab_log:
    st.subheader("📜 Log")
    if st.session_state.log_lines:
        st.code("\n".join(st.session_state.log_lines[-500:]), language="text")
    else:
        st.info("Log is empty.")